<script setup lang="ts">
import SavedResultNotice from '../../components/SavedResultNotice.vue'
import StockQuestionPanel from './StockQuestionPanel.vue'
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useAuthStore} from '../../stores/auth'
import {ApiError} from '../../api/auth'
import {analyses,generateAnalysis,predictionOptions,type PredictionOptions,type AnalysisList,type AnalysisInput,type AnalysisAttempt} from '../../api/analyses'
const props=defineProps<{instrumentId:string;rangeFrom:string;rangeTo:string;marketVersionId:string|null;hasBars:boolean}>()
const auth=useAuthStore(),view=ref<AnalysisList|null>(null),loading=ref(false),generating=ref(false),error=ref(''),pending=ref<AnalysisInput|null>(null),attempt=ref<AnalysisAttempt|null>(null),selected=ref(''),page=ref(1)
const choices=ref<PredictionOptions|null>(null),choicePage=ref(1),choiceLoading=ref(false),choiceError=ref(''),selectedPrediction=ref(''),knownChoices=ref(new Set<string>());
const historyFrom=ref(props.rangeFrom),historyTo=ref(props.rangeTo)
let generation=0,choiceGeneration=0
const result=computed(()=>view.value?.items.find(x=>x.analysisId===selected.value)||view.value?.items[0]||null)
const busy=computed(()=>loading.value||generating.value)
const failure=computed(()=>{const code=attempt.value?.errorCode;if(!code)return '';if(code==='AI_SERVICE_FROZEN')return 'AI分析服务已暂停，需管理员检查云端服务状态。';if(code==='AI_OUTPUT_INVALID'||code==='ANALYSIS_EVIDENCE_INVALID')return '返回的分析未通过数据核对，可明确重试。';if(code==='AI_RATE_LIMITED')return '云端请求受到频率限制，请稍后重试。';return '本次AI分析未完成，行情与已有分析仍保留。'})
const oldVersion=computed(()=>result.value&&result.value.context.marketVersionId!==props.marketVersionId)
const resultPrediction=computed(()=>result.value?.context.prediction||null)
const differentSelection=computed(()=>!!result.value&&(resultPrediction.value?.predictionId||'')!==selectedPrediction.value)
const unavailableSelection=computed(()=>!!selectedPrediction.value&&!pending.value&&(choiceLoading.value||!!choiceError.value||!knownChoices.value.has(selectedPrediction.value)))
async function loadChoices(turn=generation){if(!auth.profile)return;const request=++choiceGeneration;choiceLoading.value=true;choiceError.value='';try{const data=await predictionOptions(props.instrumentId,choicePage.value);if(turn===generation&&request===choiceGeneration){choices.value=data;data.items.forEach(x=>knownChoices.value.add(x.predictionId));}}catch(e){if(turn===generation&&request===choiceGeneration)choiceError.value='预测候选查询失败：'+(e as Error).message}finally{if(turn===generation&&request===choiceGeneration)choiceLoading.value=false}}
function moveChoices(delta:number){choicePage.value+=delta;void loadChoices()}
function currentInput(operationId:string):AnalysisInput{return {operationId,instrumentId:props.instrumentId,from:props.rangeFrom,to:props.rangeTo,marketVersionId:props.marketVersionId!,predictionId:selectedPrediction.value||null}}
function requestKey(){return 'aistock:stock-analysis-request:'+JSON.stringify([auth.profile?.userId,props.instrumentId,props.rangeFrom,props.rangeTo])}
function saveRequest(input:AnalysisInput|null){
 pending.value=input
 if(!auth.profile)return
 try{
  if(input)sessionStorage.setItem(requestKey(),JSON.stringify(input))
  else sessionStorage.removeItem(requestKey())
 }catch{}
}
function restoreRequest():AnalysisInput|null{
 if(!auth.profile)return null
 try{
  const input=JSON.parse(sessionStorage.getItem(requestKey())||'null') as AnalysisInput|null
  if(input&&input.instrumentId===props.instrumentId&&input.from===props.rangeFrom&&input.to===props.rangeTo&&typeof input.operationId==='string'&&typeof input.marketVersionId==='string'&&(input.predictionId==null||typeof input.predictionId==='string'))return input
 }catch{}
 return null
}
function applyAttempt(a:AnalysisAttempt|null){attempt.value=a;if(a?.state==='RUNNING'&&!pending.value&&a.marketVersionId&&a.instrumentId&&a.from&&a.to){saveRequest({operationId:a.operationId,instrumentId:a.instrumentId,marketVersionId:a.marketVersionId,from:a.from,to:a.to,predictionId:a.predictionId||null});selectedPrediction.value=a.predictionId||'';}if(a&&pending.value?.operationId===a.operationId&&a.state!=='RUNNING')saveRequest(null)}
async function refresh(turn=generation){if(!auth.profile||!props.rangeFrom||!props.rangeTo)return;loading.value=true;error.value='';try{const v=await analyses(props.instrumentId,historyFrom.value,historyTo.value,page.value);if(turn!==generation)return;view.value=v;applyAttempt(v.latestAttempt);if(!v.items.some(x=>x.analysisId===selected.value))selected.value=v.items[0]?.analysisId||''}catch(e){if(turn===generation)error.value='查询失败：'+(e as Error).message}finally{if(turn===generation)loading.value=false}}
async function generate(){if(busy.value||unavailableSelection.value||!auth.profile||!pending.value&&(!props.hasBars||!props.marketVersionId))return;const turn=generation;generating.value=true;error.value='';const input=pending.value||currentInput(crypto.randomUUID());saveRequest(input);try{const a=await generateAnalysis(input);if(turn!==generation)return;applyAttempt(a);if(a.state==='SUCCEEDED'){historyFrom.value=props.rangeFrom;historyTo.value=props.rangeTo;page.value=1;selected.value='';await refresh(turn)}}catch(e){if(turn===generation){error.value='生成未完成：'+(e as Error).message;if(e instanceof ApiError&&['AI_BUSY','AI_REQUEST_INVALID','ANALYSIS_EVIDENCE_INVALID','AI_NOT_CONFIGURED','RESOURCE_NOT_FOUND','MARKET_VERSION_UNAVAILABLE','ANALYSIS_PREDICTION_INVALID'].includes(e.code))saveRequest(null)}}finally{if(turn===generation)generating.value=false}}
function movePage(delta:number){page.value+=delta;selected.value='';void refresh()}
watch(()=>[props.instrumentId,props.rangeFrom,props.rangeTo,auth.profile?.userId],()=>{generation++;historyFrom.value=props.rangeFrom;historyTo.value=props.rangeTo;view.value=null;pending.value=restoreRequest();attempt.value=null;selected.value='';page.value=1;error.value='';loading.value=false;generating.value=false;choices.value=null;choicePage.value=1;choiceLoading.value=false;choiceError.value='';selectedPrediction.value=pending.value?.predictionId||'';knownChoices.value=new Set();void refresh(generation);void loadChoices(generation)},{immediate:true})
onBeforeUnmount(()=>{generation++;choiceGeneration++})
const titles:Record<string,string>={overview:'行情概览',readout:'指标解读',risk:'风险与限制'}
function time(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}
</script>
<template><section class="ai-panel" aria-labelledby="stock-ai-heading"><div class="heading"><div><p class="eyebrow">读懂行情</p><h2 id="stock-ai-heading">AI股票分析</h2></div><div class="actions"><button data-refresh :disabled="busy||!auth.profile" @click="refresh()">刷新分析记录</button><button data-testid="generate-analysis" class="primary" :disabled="busy||unavailableSelection||!auth.profile||(!pending&&(!hasBars||!marketVersionId||view?.configured===false))" @click="generate">{{generating?'正在生成…':pending?'核对原请求（可能继续处理）':result?'基于当前行情生成分析':'生成AI分析'}}</button></div></div><div class="history-query"><label>过往分析起始日期 <input data-testid="history-from" v-model="historyFrom" type="date" :disabled="busy||!!pending" /></label><label>结束日期 <input data-testid="history-to" v-model="historyTo" type="date" :disabled="busy||!!pending" /></label><button data-testid="query-history" :disabled="busy||!!pending||!auth.profile||!historyFrom||!historyTo||historyFrom>historyTo" @click="page=1;selected='';refresh()">查询过往分析</button></div><p class="hint">记录查询可选择过去的范围；生成新分析仍使用上方行情范围。</p><div class="prediction-choice"><label>引用本人已有预测 <select data-testid="prediction-choice" v-model="selectedPrediction" :disabled="busy||!!pending||choiceLoading"><option value="">不引用预测，仅分析行情</option><option v-if="selectedPrediction&&!choices?.items.some(x=>x.predictionId===selectedPrediction)" :value="selectedPrediction">已保留选择（当前页未列出）</option><option v-for="option in choices?.items||[]" :key="option.predictionId" :value="option.predictionId">原点 {{option.originDate}} · 目标 {{option.targetFrom}} 至 {{option.targetTo}} · {{option.artifactId}} · {{time(option.createdAt)}}</option></select></label><button data-testid="refresh-predictions" :disabled="busy||choiceLoading||!!pending||!auth.profile" @click="loadChoices()">刷新预测候选</button><span v-if="choiceLoading" role="status">正在查询本人同股票预测…</span><p v-if="choiceError" role="status">{{choiceError}}；可明确选择不引用预测，继续行情分析。</p><p v-else-if="choices&&!choices.total" class="hint">尚无本人同股票的可引用成功预测，可继续分析行情或从上方发起预测。</p><div v-if="choices&&choices.total>choices.size" class="actions"><button :disabled="choiceLoading||busy||!!pending||choicePage===1" @click="moveChoices(-1)">上一页候选</button><span>候选第{{choicePage}}页</span><button :disabled="choiceLoading||busy||!!pending||choicePage*choices.size>=choices.total" @click="moveChoices(1)">下一页候选</button></div></div><p class="hint">分析绑定生成时的行情版本。刷新仅查询已保存记录，点击生成才调用 AI。分析仅供辅助参考。</p><p v-if="!hasBars" class="hint">此范围没有有效行情，暂不能生成分析。</p><p v-if="view?.configured===false" role="status">AI分析尚未配置，行情仍可查看。</p><p v-if="error" role="alert">{{error}}</p><p v-if="generating" role="status">正在核对数据并生成分析，请稍候。</p><p v-else-if="pending" role="status">原请求状态尚未确认。可离开本页，返回相同股票和日期范围后刷新分析记录。</p><p v-if="failure" role="status">{{failure}}</p><template v-if="result"><SavedResultNotice :label="oldVersion ? '历史分析 · 使用旧行情版本' : '已保存分析'" :saved-at="result.createdAt">
 <span>行情截至 {{result.context.facts.AS_OF}}</span><span>{{result.context.provider}} · 未复权</span>
 <span>分析所用行情版本 {{result.context.marketVersionId}}</span>
 <template #actions><a href="#stock-daily-heading">查看当前日线</a></template>
</SavedResultNotice><label v-if="view&&view.items.length>1">选择已保存分析 <select v-model="selected"><option v-for="item in view.items" :key="item.analysisId" :value="item.analysisId">{{time(item.createdAt)}}</option></select></label><p v-if="differentSelection" class="warning">当前选择与这份已保存分析不同；以下内容仍使用保存时的预测依据，选择不会重新生成。</p><section v-if="resultPrediction" aria-label="本次引用的预测"><h3>本次引用的预测</h3><p>原点：{{resultPrediction.originDate}} · 模型：{{resultPrediction.artifactId}}</p><p>验证版本：{{resultPrediction.verificationVersionId||'尚无有效验证版本'}}</p><table><caption>目标日与预测参考价格（非实际行情）</caption><thead><tr><th>目标日期</th><th>预测参考价格</th></tr></thead><tbody><tr v-for="step in 5" :key="step"><td>{{result.context.facts['PRED_D'+step]}}</td><td>{{result.context.facts['PRED_P'+step]}}</td></tr></tbody></table><a :href="'/predictions?predictionId='+encodeURIComponent(resultPrediction.predictionId)">查看原预测</a></section><article v-for="paragraph in result.paragraphs" :key="paragraph.kind"><h3>{{paragraph.kind==='readout'&&resultPrediction?'指标与预测解读':titles[paragraph.kind]||paragraph.kind}}</h3><p>{{paragraph.text}}</p><small>引用依据：{{paragraph.refs.join('、')}}</small></article><details><summary>查看分析依据</summary><dl><dt>所选范围</dt><dd>{{result.context.from}} 至 {{result.context.to}}</dd><dt>行情版本</dt><dd>{{result.context.marketVersionId}}</dd><template v-if="resultPrediction"><dt>引用预测编号／输入版本</dt><dd>{{resultPrediction.predictionId}} ／ {{resultPrediction.inputVersionId}}</dd><dt>预测原始行情版本／模型依据</dt><dd>{{resultPrediction.rawVersionId}} ／ {{resultPrediction.manifestHash}} ／ {{resultPrediction.checkpointHash}}</dd></template><dt>指标公式／提示词版本</dt><dd>{{result.context.formulaVersion}} ／ {{result.context.promptVersion}}</dd><dt>文本模型／生成时间</dt><dd>{{result.context.providerModel}} ／ {{time(result.createdAt)}}</dd><template v-for="(value,key) in result.context.facts" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl></details><StockQuestionPanel :analysis-id="result.analysisId" :instrument-id="instrumentId" /></template><p v-else-if="!busy&&!failure&&!error" class="hint">还没有此范围的分析记录，可以点击生成；先生成或选择一份已保存分析，再提问。</p><div v-if="view&&view.total>10" class="actions pagination"><button :disabled="busy||page===1" @click="movePage(-1)">上一页</button><span>第{{page}}页</span><button :disabled="busy||page*10>=view.total" @click="movePage(1)">下一页</button></div></section></template>
<style scoped>.history-query{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;margin:16px 0}.history-query label{display:flex;flex-direction:column;gap:8px}.history-query input{font:inherit;padding:10px;border:1px solid var(--border);border-radius:8px;min-height:24px}.ai-panel{margin-top:24px;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:24px}.heading,.actions,.result-meta{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}h2{font-size:22px;margin:4px 0}h3{font-size:17px;margin:0 0 8px}.hint,small,.result-meta,dd{color:var(--muted)}p{line-height:1.7;overflow-wrap:anywhere}.result-meta{justify-content:flex-start;font-size:14px}article{border:1px solid var(--border);border-radius:10px;padding:18px;margin-top:16px;background:white}button,select{font:inherit;min-height:44px;padding:10px 14px;border:1px solid var(--border);border-radius:8px;background:white;color:var(--ink)}button{cursor:pointer}button.primary{background:var(--accent);color:white}button:disabled{opacity:.6;cursor:default}button:focus-visible,summary:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}summary{cursor:pointer;min-height:44px;padding-top:16px}dt{font-weight:600}dd{margin:4px 0 12px;overflow-wrap:anywhere}.prediction-choice{margin:18px 0;padding:16px;border:1px solid var(--border);border-radius:10px}.prediction-choice label{display:flex;flex-direction:column;gap:8px;flex:1}.prediction-choice select{max-width:100%;width:100%}.prediction-choice button{margin-top:10px}table{border-collapse:collapse;width:100%;margin:12px 0}th,td{padding:10px;text-align:left;border-bottom:1px solid var(--border)}caption{text-align:left;color:var(--muted)}.pagination{margin-top:18px;justify-content:flex-end}.warning{border-left:3px solid var(--accent);padding-left:12px}@media(max-width:680px){.ai-panel{padding:18px}.actions{width:100%}}</style>
